import prisma from "@/lib/prisma";
import GreetingTVSettings from "@/components/dashboard/greeting-tv-settings";
// import { auth } from "@/lib/auth"; // sesuaikan

export const dynamic = "force-dynamic";

export default async function GreetingTVPage() {
  // const session = await auth();

  const invitations = await prisma.invitation.findMany({
    where: { userId: session.user.id },
    select: {
      id: true,
      brideName: true,
      groomName: true,
      tvEnabled: true,
      tvBackground: true,
      tvCouplePhoto: true,
      tvLogo: true,
      tvDuration: true,
      tvSoundEnabled: true,
      tvAnimationEnabled: true,
      tvFontSize: true,
      tvFullscreen: true,
      tvCategoryColors: true,
    },
  });

  // Kategori tamu yang sudah ada, per undangan
  const rows = await prisma.guest.findMany({
    where: {
      invitationId: { in: invitations.map((i) => i.id) },
      category: { not: null },
    },
    distinct: ["invitationId", "category"],
    select: { invitationId: true, category: true },
  });

  const withCategories = invitations.map((inv) => ({
    ...inv,
    guestCategories: rows
      .filter((r) => r.invitationId === inv.id && r.category.trim())
      .map((r) => r.category.trim()),
  }));

  return (
    <GreetingTVSettings
      invitations={JSON.parse(JSON.stringify(withCategories))}
    />
  );
}
